export default function build({ THREE, add, task }) {
  // Helper to place a ramp segment (floor + 2 sidewalls) from p0 to p1 (centerline of top surface of floor)
  function addChute(p0, p1, { width = 0.10, wallHeight = 0.11, thickness = 0.016, floorColor = '#e0a96d', wallColor = '#2b4c7e' } = {}) {
    const dx = p1[0] - p0[0];
    const dy = p1[1] - p0[1];
    const dz = p1[2] - p0[2];
    const horiz = Math.hypot(dx, dz);
    const len = Math.hypot(horiz, dy);
    const alpha = Math.atan2(dz, dx);
    const ry = -alpha;
    const rz = Math.atan2(dy, horiz); // negative when going downhill

    // Unit vectors of local axes
    const cx = Math.cos(rz), sx = Math.sin(rz);
    const ca = Math.cos(alpha), sa = Math.sin(alpha);
    const ux = [cx * ca, sx, cx * sa];
    const uy = [-sx * ca, cx, -sx * sa];
    const uz = [-sa, 0, ca];

    const mid = [(p0[0] + p1[0]) / 2, (p0[1] + p1[1]) / 2, (p0[2] + p1[2]) / 2];
    const totalWidth = width + 2 * thickness;

    // Floor center is offset by -thickness/2 along uy
    const floorPos = [
      mid[0] - uy[0] * (thickness / 2),
      mid[1] - uy[1] * (thickness / 2),
      mid[2] - uy[2] * (thickness / 2),
    ];
    add.box({
      size: [len, thickness, totalWidth],
      position: floorPos,
      rotation: [0, ry, rz],
      color: floorColor,
    });

    // Left and right sidewalls
    for (const side of [-1, 1]) {
      const zOff = side * (width / 2 + thickness / 2);
      const yOff = wallHeight / 2;
      const wallPos = [
        mid[0] + uy[0] * yOff + uz[0] * zOff,
        mid[1] + uy[1] * yOff + uz[2] * 0,
        mid[2] + uy[2] * yOff + uz[2] * zOff,
      ];
      add.box({
        size: [len, wallHeight, thickness],
        position: wallPos,
        rotation: [0, ry, rz],
        color: wallColor,
      });
    }
  }

  // Direction unit vector from start [-0.85, -0.3] to cup [0.8, 0.3]
  // dx = 1.65, dz = 0.60, horiz = 1.7557
  // Start hopper behind [-0.85, -0.3]:
  // At u = -0.11m behind start: [-0.953, -0.338]
  // End of chute just before cup center [0.8, 0.3]:
  // Let's check waypoints along the line from [-0.953, -0.338] to [0.76, 0.285]
  const w0 = [-0.955, 0.72, -0.338];
  const w1 = [-0.38, 0.51, -0.129];
  const w2 = [0.20, 0.30, 0.082];
  const w3 = [0.755, 0.10, 0.284];

  // Segment 1: catch hopper + upper ramp (slightly wider to catch all drops)
  addChute(w0, w1, { width: 0.11, wallHeight: 0.14, thickness: 0.016, floorColor: '#d99b52', wallColor: '#1f3a60' });
  // Segment 2: middle ramp (narrows slightly to 0.095m, overlapped slightly with w1)
  const w1_ov = [-0.40, 0.515, -0.136];
  addChute(w1_ov, w2, { width: 0.09, wallHeight: 0.12, thickness: 0.016, floorColor: '#e0a96d', wallColor: '#2b4c7e' });
  // Segment 3: lower ramp leading right to the cup rim
  const w2_ov = [0.18, 0.305, 0.075];
  addChute(w2_ov, w3, { width: 0.076, wallHeight: 0.12, thickness: 0.016, floorColor: '#d99b52', wallColor: '#1f3a60' });

  const alpha = Math.atan2(0.6, 1.65);
  const ry = -alpha;
  const ca = Math.cos(alpha), sa = Math.sin(alpha);
  const uz = [-sa, 0, ca];

  // Backstop at the top of the catch hopper (w0)
  add.box({
    size: [0.02, 0.20, 0.15],
    position: [w0[0], w0[1] + 0.08, w0[2]],
    rotation: [0, ry, 0],
    color: '#1f3a60',
  });

  // Catching enclosure / drop chimney around the cup at [0.8, 0, 0.3]
  // Back wall behind the cup (along +u direction from cup center, at distance 0.058m)
  const cupX = 0.8, cupZ = 0.3;
  const backDist = 0.056;
  add.box({
    size: [0.02, 0.24, 0.14],
    position: [cupX + ca * backDist, 0.14, cupZ + sa * backDist],
    rotation: [0, ry, 0],
    color: '#c85a32',
  });

  // Side containment walls flanking the cup so the marble drops straight into r < 0.07
  for (const side of [-1, 1]) {
    const sDist = side * 0.058;
    add.box({
      size: [0.15, 0.22, 0.02],
      position: [cupX + uz[0] * sDist - ca * 0.01, 0.13, cupZ + uz[2] * sDist - sa * 0.01],
      rotation: [0, ry, 0],
      color: '#2b4c7e',
    });
  }

  // Top baffle / roof over the cup drop zone to prevent any vertical bounce-out
  add.box({
    size: [0.15, 0.02, 0.14],
    position: [cupX - ca * 0.005, 0.24, cupZ - sa * 0.005],
    rotation: [0, ry, -0.15],
    color: '#c85a32',
  });

  // Front lower lip above cup rim (from y=0.06 to y=0.095, leaving entry slot above y=0.095)
  // Wait: the ramp w3 arrives at y=0.10, so a front lip below the ramp floor at [cupX - ca*0.058] from y=0.06 to y=0.10
  // completely seals the cup below y=0.10 on the upstream side too!
  add.box({
    size: [0.02, 0.05, 0.12],
    position: [cupX - ca * 0.056, 0.08, cupZ - sa * 0.056],
    rotation: [0, ry, 0],
    color: '#1f3a60',
  });
}

