export default function build({ THREE, add, task }) {
  // Helper to place a ramp segment (floor + 2 sidewalls) with explicit length `len` along p0 -> p1 direction
  function addChute(p0, p1, { width = 0.10, wallHeight = 0.12, thickness = 0.016, floorColor = '#e0a96d', wallColor = '#2b4c7e' } = {}) {
    const dx = p1[0] - p0[0];
    const dy = p1[1] - p0[1];
    const dz = p1[2] - p0[2];
    const horiz = Math.hypot(dx, dz);
    const len = Math.hypot(horiz, dy);
    const alpha = Math.atan2(dz, dx);
    const ry = -alpha;
    const rz = Math.atan2(dy, horiz); // negative when going downhill

    // Unit vectors of local axes
    const cx = Math.cos(rz), sx = Math.sin(rz);
    const ca = Math.cos(alpha), sa = Math.sin(alpha);
    const uy = [-sx * ca, cx, -sx * sa];
    const uz = [-sa, 0, ca];

    const mid = [(p0[0] + p1[0]) / 2, (p0[1] + p1[1]) / 2, (p0[2] + p1[2]) / 2];
    const totalWidth = width + 2 * thickness;

    // Floor center is offset by -thickness/2 along uy
    const floorPos = [
      mid[0] - uy[0] * (thickness / 2),
      mid[1] - uy[1] * (thickness / 2),
      mid[2] - uy[2] * (thickness / 2),
    ];
    add.box({
      size: [len, thickness, totalWidth],
      position: floorPos,
      rotation: [0, ry, rz],
      color: floorColor,
    });

    // Left and right sidewalls (make len slightly smaller by 0.001 so floor comes before walls if needed, both fine)
    for (const side of [-1, 1]) {
      const zOff = side * (width / 2 + thickness / 2);
      const yOff = wallHeight / 2;
      const wallPos = [
        mid[0] + uy[0] * yOff + uz[0] * zOff,
        mid[1] + uy[1] * yOff,
        mid[2] + uy[2] * yOff + uz[2] * zOff,
      ];
      add.box({
        size: [len, wallHeight, thickness],
        position: wallPos,
        rotation: [0, ry, rz],
        color: wallColor,
      });
    }
  }

  // Line from start [-0.85, -0.30] to cup [0.80, 0.30]:
  // Unit horizontal vector: ca = 1.65 / 1.755705 = 0.939793, sa = 0.60 / 1.755705 = 0.341743
  // Parameter s = horizontal distance from [-0.85, -0.30] along (ca, sa):
  // x(s) = -0.85 + s * ca, z(s) = -0.30 + s * sa
  // Cup center is at s = 1.755705.
  const alpha = Math.atan2(0.60, 1.65);
  const ry = -alpha;
  const ca = Math.cos(alpha), sa = Math.sin(alpha);
  const uz = [-sa, 0, ca];
  const pt = (s, y) => [-0.85 + s * ca, y, -0.30 + s * sa];

  // Segment 1: s from -0.18 to +0.58 (horiz = 0.76m, dy = -0.27m -> len = 0.806m, largest s[0]!)
  // At s = 0 (marble drop [-0.85, -0.30]), floor y is ~0.736m, sidewalls go up to 0.736 + 0.18 = 0.916m.
  // Width is 0.16m (half-width 0.08m > max start offset + radius), so marble spawns cleanly inside the channel!
  addChute(pt(-0.18, 0.80), pt(0.58, 0.53), {
    width: 0.16,
    wallHeight: 0.18,
    thickness: 0.016,
    floorColor: '#d99b52',
    wallColor: '#1f3a60',
  });

  // Segment 2: s from +0.52 to +1.18 (horiz = 0.66m, dy = -0.23m -> len = 0.699m, second largest s[0]!)
  // Note: at s = 0.58, Segment 1 floor is at y = 0.53; Segment 2 starts at s = 0.52 at y = 0.525 (just under Segment 1 for a smooth step-down!)
  addChute(pt(0.52, 0.525), pt(1.18, 0.295), {
    width: 0.12,
    wallHeight: 0.16,
    thickness: 0.016,
    floorColor: '#e0a96d',
    wallColor: '#2b4c7e',
  });

  // Segment 3: s from +1.12 to +1.70 (horiz = 0.58m, dy = -0.20m -> len = 0.613m, third largest s[0]!)
  // Ends at s = 1.70 (0.055m before cup center s = 1.7557) at y = 0.09m (just above cup rim y = 0.06m!)
  addChute(pt(1.12, 0.29), pt(1.70, 0.09), {
    width: 0.085,
    wallHeight: 0.16,
    thickness: 0.016,
    floorColor: '#d99b52',
    wallColor: '#1f3a60',
  });

  // Converging guide walls inside Segment 1 -> 2 and Segment 2 -> 3 so marble never catches on sidewall step-ins!
  // Wait: if all 3 segments have the SAME inner width = 0.11m (or funnel smoothly), can the marble ever catch a sidewall edge?
  // Wait: at the cup, innerRadius = 0.07m (diameter = 0.14m).
  // Wait: if inner width is 0.10m, let's check if any trial hits the sidewall at t=0 when width = 0.10m!
  // Max lateral offset at t=0: |dx * (-sa) + dz * ca| <= 0.03 * (|sa| + |ca|) = 0.03 * 1.2815 = 0.0384m.
  // Plus marble radius 0.025m = 0.0634m!
  // So if inner width is 0.13m everywhere (half-width = 0.065m > 0.0634m), AND at the cup end two angled funnel cheeks narrow it from 0.13m to 0.08m!

  // Cup trap / drop chimney around [0.8, 0, 0.3] (s = 1.7557):
  const cupS = Math.hypot(1.65, 0.60);
  // Backstop wall behind the cup (at s = cupS + 0.055)
  const backP = pt(cupS + 0.055, 0.16);
  add.box({
    size: [0.02, 0.26, 0.16],
    position: backP,
    rotation: [0, ry, 0],
    color: '#c85a32',
  });

  // Left and right chimney walls around the cup (angled inward slightly from width 0.12 to 0.09)
  for (const side of [-1, 1]) {
    const sDist = side * 0.056;
    const midCup = pt(cupS - 0.01, 0.15);
    add.box({
      size: [0.18, 0.24, 0.02],
      position: [midCup[0] + uz[0] * sDist, midCup[1], midCup[2] + uz[2] * sDist],
      rotation: [0, ry + side * 0.12, 0],
      color: '#2b4c7e',
    });
  }

  // Roof baffle over the cup so high-speed or bumped marbles bounce straight down into the cup
  const roofP = pt(cupS - 0.01, 0.26);
  add.box({
    size: [0.18, 0.02, 0.16],
    position: roofP,
    rotation: [0, ry, -0.20],
    color: '#c85a32',
  });

  // Upstream lower collar wall between cup rim (y=0.06) and Segment 3 floor (y=0.095)
  const lipP = pt(cupS - 0.058, 0.075);
  add.box({
    size: [0.02, 0.04, 0.13],
    position: lipP,
    rotation: [0, ry, 0],
    color: '#1f3a60',
  });
}

